def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v = v.split('+')[0]

        # Split into core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if identifier is all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # Version without pre-release sorts after version with pre-release
        if not pre1 and not pre2:
            return 0
        if not pre1:
            return 1
        if not pre2:
            return -1

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            type1, val1 = pre1[i]
            type2, val2 = pre2[i]

            # All-digit identifiers sort before other identifiers
            if type1 != type2:
                return -1 if type1 < type2 else 1

            # Compare values (numeric or string)
            if val1 < val2:
                return -1
            elif val1 > val2:
                return 1

        # Fewer identifiers sort first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1

        return 0

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)
        return (major, minor, patch, prerelease)

    # Sort using a stable sort with custom comparison
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    def compare_versions(item1, item2):
        v1, idx1 = item1
        v2, idx2 = item2

        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare major, minor, patch
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # Compare pre-release
        pre_cmp = compare_prerelease(pre1, pre2)
        if pre_cmp != 0:
            return pre_cmp

        # Equal precedence: maintain input order
        return -1 if idx1 < idx2 else (1 if idx1 > idx2 else 0)

    from functools import cmp_to_key
    sorted_items = sorted(indexed_versions, key=cmp_to_key(compare_versions))
    return [v for v, _ in sorted_items]

